  "lumi.text[5]": { al: "një gjarpër fle në lumë.", en: "A serpent sleeps in the river." },
  "lumi.text[6]": { al: "gjarpri nuk është më këtu. vendi pranë lumit është i sigurt.", en: "The serpent is gone. The place by the river is safe." },
  "lumi.text[7]": { al: "larg, qyteti i Zjermës ka ujë përsëri.", en: "Far away, Zjerma's city has water again." },
  "lumi.text[8]": { al: "larg një plak rri mbi një gur dhe flet për ar.", en: "Far away, an old man sits on a stone and speaks of gold." },
  "lumi.text[9]": { al: "natën plaku nuk është këtu.", en: "At night, the old man is not here." },
  "lumi.text[10]": { al: "larg rri një liqen i qetë.", en: "A still lake lies in the distance." },
  "lumi.text[11]": { al: "poshtë është një urë e vjetër.", en: "An old bridge lies downstream." },
  "lumi.text[12]": { al: "nata vjen.", en: "Night falls." },
  "lumi.text[13]": { al: "natën uji është i bardhë nën hënë.", en: "At night, the water gleams white beneath the moon." },
  "lumi.text[14]": { al: "natën lumi është i bardhë nën hënë.", en: "At night, the river gleams white beneath the moon." },
  "lumi.text[15]": { al: "dielli del mbi malet.", en: "The sun rises over the mountains." },

  "veraDite1.text[0]": { al: "sot fshati bën një festë.", en: "Today the village holds a festival." },
